using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PowderSettingsOperations:RefCounted
{
    private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    public double number(Settings values,string key,double fallback,double low,double high){double value=Get(values,key,fallback).AsDouble();return double.IsFinite(value)?Math.Clamp(value,low,high):fallback;}
    public Settings effective(Settings values){var result=values.Duplicate();double flow=number(values,"powder_flowability",.5,0,1),friction=number(values,"powder_friction",.6,0,2);bool advanced=Get(values,"powder_advanced_material",false).AsBool();double staticFriction=advanced?number(values,"powder_static_friction",.66,0,3):friction*Mathf.Lerp(1.8,.4,flow);result["static_friction"]=staticFriction;result["dynamic_friction"]=advanced?Math.Min(staticFriction,number(values,"powder_dynamic_friction",.495,0,3)):staticFriction*.75;result["rolling"]=advanced?number(values,"powder_rolling",.06,0,1):friction*(1-flow)*.2;result["cohesion"]=number(values,"powder_cohesion",0,0,10);result["separation"]=number(values,"powder_bond_range",.5,.05,2);result["packing"]=number(values,"powder_compaction",.98,.05,1);result["restitution"]=number(values,"powder_restitution",.05,0,1);result["damping"]=number(values,"powder_damping",.08,0,20);result["contact_damping"]=number(values,"powder_contact_damping",.2,0,1);result["density"]=number(values,"powder_density",1600,1,30000);result["gravity_scale"]=number(values,"powder_gravity",1,0,10);result["wind_influence"]=number(values,"powder_wind",1,0,20);result["air_drag"]=number(values,"powder_air_drag",.47,0,5);result["turbulence"]=number(values,"powder_turbulence",0,0,20);result["fluid_strength"]=number(values,"powder_fluid",1,0,2);result["max_speed"]=number(values,"powder_max_speed",20,.1,100);result["sleep_speed"]=number(values,"powder_sleep_speed",.025,.001,.2);result["sleep_delay"]=number(values,"powder_sleep_delay",.4,.05,5);int quality=Math.Clamp(Get(values,"powder_quality",1).AsInt32(),0,2);result["substeps"]=Math.Clamp(Get(values,"powder_substeps",2).AsInt32()+new[]{-1,0,2}[quality],1,12);result["iterations"]=Math.Clamp(Get(values,"powder_iterations",6).AsInt32()+new[]{-2,0,4}[quality],2,16);return result;}
    public void switch_mode(RefCounted model,GArray actors,bool advanced){var before=new GArray();var after=new GArray();foreach(var value in actors){var actor=value.As<Resource>();if(actor.Get("type_id").AsString()!="powder")continue;var values=actor.Get("values").AsGodotDictionary().Duplicate(true);var sampled=effective(values);before.Add(new Settings{["actor"]=actor,["values"]=values.Duplicate(true)});if(advanced){values[new StringName("powder_static_friction")]=sampled["static_friction"];values[new StringName("powder_dynamic_friction")]=sampled["dynamic_friction"];values[new StringName("powder_rolling")]=sampled["rolling"];}else values[new StringName("powder_friction")]=sampled["static_friction"].AsDouble()/Mathf.Lerp(1.8,.4,number(values,"powder_flowability",.5,0,1));values[new StringName("powder_advanced_material")]=advanced;after.Add(new Settings{["actor"]=actor,["values"]=values});}var history=model.Get("history").As<UndoRedo>();var action=new PowderSettingsHistoryAction(model,before,after);history.CreateAction("Powder contact controls");history.AddDoMethod(new Callable(action,nameof(PowderSettingsHistoryAction.restore_after)));history.AddUndoMethod(new Callable(action,nameof(PowderSettingsHistoryAction.restore_before)));history.AddDoReference(action);history.CommitAction();}
    public void assign(Variant reference,GArray entries){var model=reference.AsGodotObject();if(model is WeakRef weak){using var target=weak.GetRef();model=target.AsGodotObject();}if(model==null)return;foreach(var value in entries){var entry=value.AsGodotDictionary();var actor=entry["actor"].As<Resource>();actor.Set("values",entry["values"].AsGodotDictionary().Duplicate(true));actor.Get("animation_previews").AsGodotDictionary().Clear();actor.EmitChanged();}model.EmitSignal("changed");}
}
